import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    try:
        n = int(data[0])
    except:
        return
    if n <= 0:
        return
    out = '\n'.join(str(i) for i in range(1, n + 1))
    sys.stdout.write(out)

if __name__ == "__main__":
    solve()
